# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14" font-weight="bold" fill="#0f172a">İSLAM KELAMINDA AKIL VE VAHİY İLİŞKİSİ (2.5)</text>\n  <rect x="20" y="45" width="215" height="198" rx="10" fill="#dbeafe" stroke="#2563eb" stroke-width="2"/>\n  <text x="127" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">Akl-ı Selim (Selim Akıl)</text>\n  <text x="35" y="92" font-size="10.5" fill="#1e3a8a">• Ön yargı, taklit ve tutkudan</text>\n  <text x="43" y="108" font-size="10.5" fill="#1e3a8a">arınmış, doğru düşünen akıldır.</text>\n  <text x="35" y="130" font-size="10.5" fill="#1e3a8a">• <tspan font-weight="bold">Görevi:</tspan> Dini sorumluluğun</text>\n  <text x="43" y="146" font-size="10.5" fill="#1e3a8a">(teklifin) ön şartıdır; vahyi</text>\n  <text x="43" y="162" font-size="10.5" fill="#1e3a8a">anlar, yorumlar ve delillendirir.</text>\n  <text x="35" y="184" font-size="10.5" fill="#1e3a8a">• <tspan font-weight="bold">Sınırı:</tspan> Gayb âlemini, ahiret</text>\n  <text x="43" y="200" font-size="10.5" fill="#1e3a8a">hallerini ve ibadet şekillerini</text>\n  <text x="43" y="216" font-size="10.5" font-weight="bold" fill="#1d4ed8">vahiy olmadan bilemez.</text>\n  <rect x="247" y="45" width="205" height="198" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="350" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#92400e">Temel Kelam İlkesi</text>\n  <rect x="260" y="84" width="180" height="68" rx="8" fill="#ffffff" stroke="#f59e0b"/>\n  <text x="350" y="105" text-anchor="middle" font-size="11" font-weight="bold" fill="#b45309">"Sahih Nakil (Vahiy) İle</text>\n  <text x="350" y="122" text-anchor="middle" font-size="11" font-weight="bold" fill="#b45309">Selim Akıl Çelişmez!"</text>\n  <text x="350" y="140" text-anchor="middle" font-size="9.5" fill="#78350f">(Her ikisinin kaynağı da Allah\'tır)</text>\n  <text x="260" y="172" font-size="10" fill="#78350f">• Akıl <tspan font-weight="bold">göz</tspan> gibidir, vahiy ise</text>\n  <text x="268" y="188" font-size="10" fill="#78350f"><tspan font-weight="bold">güneş ışığı</tspan> gibidir (Gazâlî).</text>\n  <text x="260" y="210" font-size="10" fill="#78350f">• Görünürde çelişki varsa metin</text>\n  <text x="268" y="226" font-size="10" font-weight="bold" fill="#92400e">akıl ilkeleriyle te\'vil edilir.</text>\n  <rect x="465" y="45" width="215" height="198" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/>\n  <text x="572" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#166534">Sahih Vahiy (Haber-i Sâdık)</text>\n  <text x="480" y="92" font-size="10.5" fill="#14532d">• Yüce Allah\'ın peygamberleri</text>\n  <text x="488" y="108" font-size="10.5" fill="#14532d">aracılığıyla bildirdiği ilahi bilgidir.</text>\n  <text x="480" y="130" font-size="10.5" fill="#14532d">• <tspan font-weight="bold">Kapsamı:</tspan> Kur\'an-ı Kerim ve</text>\n  <text x="488" y="146" font-size="10.5" fill="#14532d">mütevatir sünnet (kesin nakil).</text>\n  <text x="480" y="168" font-size="10.5" fill="#14532d">• <tspan font-weight="bold">İşlevi:</tspan> Aklın ulaşamadığı</text>\n  <text x="488" y="184" font-size="10.5" fill="#14532d">gayb, ahiret, sıfatlar ve kulluk</text>\n  <text x="488" y="200" font-size="10.5" fill="#14532d">esaslarını kesin bilgiyle</text>\n  <text x="488" y="216" font-size="10.5" font-weight="bold" fill="#15803d">aydınlatır ve akla rehberlik eder.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14" font-weight="bold" fill="#0f172a">KELAM İLMİNDE BİLGİ KAYNAKLARI VE DELİL TÜRLERİ (2.6)</text>\n  <rect x="20" y="45" width="320" height="195" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="180" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1e40af">1. Naklî (Sem\'î / Şer\'î) Deliller</text>\n  <text x="35" y="94" font-size="10.5" fill="#1e3a8a">• Kaynağı vahiy ve peygamber haberi olan delillerdir.</text>\n  <text x="35" y="116" font-size="10.5" font-weight="bold" fill="#1d4ed8">• Sübût (Kaynak) ve Delâlet (Anlam) Yönü:</text>\n  <text x="43" y="134" font-size="10" fill="#1e3a8a">1. <tspan font-weight="bold">Sübûtu ve Delâleti Kat\'î (Kesin):</tspan></text>\n  <text x="53" y="150" font-size="10" fill="#1e3a8a">Anlamı açık (muhkem) Kur\'an ayetleri ve</text>\n  <text x="53" y="164" font-size="10" fill="#1e3a8a">mütevatir hadisler → <tspan font-weight="bold">İtikatta bağlayıcı delildir!</tspan></text>\n  <text x="43" y="186" font-size="10" fill="#1e3a8a">2. <tspan font-weight="bold">Zannî Haber (Âhâd Hadisler):</tspan></text>\n  <text x="53" y="202" font-size="10" fill="#1e3a8a">Mütevatir derecesine ulaşmayan rivayetler amelde</text>\n  <text x="53" y="218" font-size="10" fill="#1e3a8a">delil olsa da inanç (akaid) esası oluşturmaz.</text>\n  <rect x="360" y="45" width="320" height="195" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="520" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#166534">2. Aklî (Nazarî) ve Gözlemsel Deliller</text>\n  <text x="375" y="94" font-size="10.5" fill="#14532d">• Kaynağı <tspan font-weight="bold">akl-ı selim</tspan> ve <tspan font-weight="bold">havâss-ı selîme</tspan> (sağlam</text>\n  <text x="383" y="110" font-size="10" fill="#14532d">duyular, deney, tecrübe, dış dünya gözlemi) olan delillerdir.</text>\n  <text x="375" y="132" font-size="10.5" font-weight="bold" fill="#15803d">• Başlıca Kelamî Akıl Yürütme Delilleri:</text>\n  <text x="383" y="150" font-size="10" fill="#14532d">1. <tspan font-weight="bold">Hudûs Delili:</tspan> Âlemin sonradan yaratılmışlığı</text>\n  <text x="383" y="168" font-size="10" fill="#14532d">2. <tspan font-weight="bold">İmkân Delili:</tspan> Mümkün varlığın Vacibü\'l-Vücud\'a muhtaçlığı</text>\n  <text x="383" y="186" font-size="10" fill="#14532d">3. <tspan font-weight="bold">Gaye ve Nizam Delili:</tspan> Evrendeki hassas ölçü ve düzen</text>\n  <text x="383" y="204" font-size="10" fill="#14532d">4. <tspan font-weight="bold">Temânu (Burhan-ı Temânu) Delili:</tspan> Tevhid ispatı</text>\n  <text x="383" y="220" font-size="10" fill="#166534">(Enbiyâ, 21/22: "Eğer yerde ve gökte Allah\'tan başka...")</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14" font-weight="bold" fill="#0f172a">KELAMDA MUHKEM - MÜTEŞÂBİH AYETLER VE TE\'VİL KAVRAMI</text>\n  <rect x="20" y="45" width="210" height="195" rx="10" fill="#dbeafe" stroke="#2563eb" stroke-width="2"/>\n  <text x="125" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">Muhkem ve Müteşâbih</text>\n  <text x="32" y="92" font-size="10.5" font-weight="bold" fill="#1d4ed8">• Muhkem Ayetler:</text>\n  <text x="40" y="108" font-size="10" fill="#1e3a8a">Anlamı açık, net ve yoruma</text>\n  <text x="40" y="122" font-size="10" fill="#1e3a8a">ihtiyaç duymayan temel</text>\n  <text x="40" y="136" font-size="10" fill="#1e3a8a">ayetlerdir (Ümmü\'l-Kitâb).</text>\n  <text x="32" y="160" font-size="10.5" font-weight="bold" fill="#1d4ed8">• Müteşâbih Ayetler:</text>\n  <text x="40" y="176" font-size="10" fill="#1e3a8a">Birden fazla anlama gelebilen,</text>\n  <text x="40" y="190" font-size="10" fill="#1e3a8a">mecaz ve temsil içeren</text>\n  <text x="40" y="204" font-size="10" fill="#1e3a8a">haberi sıfat ayetleridir</text>\n  <text x="40" y="218" font-size="10" fill="#1e3a8a">(Yed/el, Vech/yüz, İstivâ).</text>\n  <rect x="245" y="45" width="210" height="195" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="350" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#92400e">Te\'vil Kavramı ve Şartları</text>\n  <text x="257" y="92" font-size="10.5" font-weight="bold" fill="#b45309">• Te\'vil Nedir?</text>\n  <text x="265" y="108" font-size="10" fill="#78350f">Bir lafzı şer\'î ve aklî bir</text>\n  <text x="265" y="122" font-size="10" fill="#78350f">delile dayanarak zahirî (ilk)</text>\n  <text x="265" y="136" font-size="10" fill="#78350f">anlamından alıp muhtemel</text>\n  <text x="265" y="150" font-size="10" fill="#78350f">diğer anlamına çevirmektir.</text>\n  <text x="257" y="174" font-size="10.5" font-weight="bold" fill="#b45309">• Örnek Te\'vil:</text>\n  <text x="265" y="190" font-size="10" fill="#78350f">"Allah\'ın eli (yed)" ifadesinin</text>\n  <text x="265" y="204" font-size="10" fill="#78350f">teşbihten kaçınmak için "Allah\'ın</text>\n  <text x="265" y="218" font-size="10" font-weight="bold" fill="#92400e">kudreti ve nimeti" olarak yorumu.</text>\n  <rect x="470" y="45" width="210" height="195" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/>\n  <text x="575" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#166534">Selef ve Halef Yöntemi</text>\n  <text x="482" y="92" font-size="10.5" font-weight="bold" fill="#15803d">• Selef-i Sâlihîn (Tefvîz):</text>\n  <text x="490" y="108" font-size="10" fill="#14532d">Müteşâbih ayetlere olduğu gibi</text>\n  <text x="490" y="122" font-size="10" fill="#14532d">iman edip gerçek manasını</text>\n  <text x="490" y="136" font-size="10" fill="#14532d">Allah\'a havale etmişlerdir.</text>\n  <text x="482" y="160" font-size="10.5" font-weight="bold" fill="#15803d">• Halef (Mâtürîdî / Eş\'arî):</text>\n  <text x="490" y="176" font-size="10" fill="#14532d">Teşbih ve tecsim (Allah\'ı</text>\n  <text x="490" y="190" font-size="10" fill="#14532d">yaratılmışlara benzetme) fitnesini</text>\n  <text x="490" y="204" font-size="10" fill="#14532d">önlemek için tevhid ilkesine</text>\n  <text x="490" y="218" font-size="10" font-weight="bold" fill="#166534">uygun te\'vil yapmışlardır.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get('bolumler', [])):
        if i < len(SVGS):
            b['gorsel'] = SVGS[i]
